def dcz(M):
    Mc = M - M.mean(0, keepdims=True) - M.mean(1, keepdims=True) + M.mean()
    dg = np.diag(Mc); off = Mc[~np.eye(len(M), dtype=bool)]
    return dg.mean() / (off.std() / np.sqrt(len(M)))
